float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 p = uv - vec2(0.5);
    p.x *= iResolution.x / iResolution.y;

    float d = length(p * 2.5);
    float angle = atan(p.y, p.x);

    float wave1 = sin(angle * 10.0 + iTime * 2.0) * 0.1 + 0.1;
    float wave2 = sin(d * 15.0 - iTime * 3.0) * 0.05 + 0.05;
    float wave3 = sin(angle * 5.0 + d * 8.0 + iTime * 1.5) * 0.08 + 0.08;

    float colorFactor = d + wave1 + wave2 + wave3;
    colorFactor += random(uv * 10.0 + iTime * 0.1) * 0.05;
    colorFactor = fract(colorFactor + iTime * 0.05);

    vec3 col = palette(colorFactor);

    fragColor = vec4(col, 1.0);
}

float sdPlane(vec3 p) { return p.y; }

float sdSphere(vec3 p, float r) { return length(p) - r; }

vec2 opU(vec2 d1, vec2 d2) { return (d1.x < d2.x) ? d1 : d2; }

vec2 map(vec3 p) {
    vec2 res = vec2(sdPlane(p), 1.0);
    res = opU(res, vec2(sdSphere(p - vec3(0.0, 0.5, 0.0), 0.5), 0.0));
    return res;
}

vec3 getNormal(vec3 p) {
    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + eps.xyy).x - map(p - eps.xyy).x,
        map(p + eps.yxy).x - map(p - eps.yxy).x,
        map(p + eps.yyx).x - map(p - eps.yyx).x
    ));
}

float softShadow(vec3 ro, vec3 rd, float k) {
    float res = 1.0;
    float t = 0.01;
    for (int i = 0; i < 64; i++) {
        float h = map(ro + rd * t).x;
        res = min(res, k * h / t);
        t += clamp(h, 0.01, 0.1);
        if (h < 0.001 || t > 10.0) break;
    }
    return clamp(res, 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(1.5 * cos(iTime * 0.1), 1.5, 1.5 * sin(iTime * 0.1));
    vec3 target = vec3(0.0, 0.5, 0.0);

    vec3 forward = normalize(target - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = normalize(cross(forward, right));

    vec3 rd = normalize(forward + right * uv.x + up * uv.y);

    float t = 0.0;
    float maxDist = 20.0;
    for (int i = 0; i < 100; i++) {
        vec2 res = map(ro + rd * t);
        if (res.x < 0.001 || t > maxDist) break;
        t += res.x;
    }

    vec3 color = vec3(0.0);
    if (t < maxDist) {
        vec3 p = ro + rd * t;
        vec3 normal = getNormal(p);

        vec3 lightPos = vec3(3.0 * cos(iTime * 0.5), 5.0, 3.0 * sin(iTime * 0.5));
        vec3 lightDir = normalize(lightPos - p);

        float diff = clamp(dot(normal, lightDir), 0.0, 1.0);

        float materialID = map(p).y;
        vec3 objColor;
        if (materialID < 0.5) { // Sphere
            objColor = vec3(0.1, 0.4, 0.7);
        } else { // Plane
            objColor = vec3(0.8, 0.8, 0.8);
        }

        float shadow = softShadow(p + normal * 0.01, lightDir, 16.0);

        color = objColor * mix(0.1, 1.0, diff * shadow);
    }

    fragColor = vec4(color, 1.0);
}

